function renderScene(){
 const doc=workspace.active,ids=new Set(doc.graph.nodes.map(n=>n.id));for(const [id,view]of sceneNodes)if(!ids.has(id)){nodeResizeObserver.unobserve(view.card);view.card.remove();sceneNodes.delete(id);}
 for(const node of doc.graph.nodes){let view=sceneNodes.get(node.id);if(view&&(view.type!==node.type||view.version!==node.version)){nodeResizeObserver.unobserve(view.card);view.card.remove();sceneNodes.delete(node.id);view=null;}if(!view){view=buildNode(node);sceneNodes.set(node.id,view);C('composer-nodes').append(view.card);nodeResizeObserver.observe(view.card);}view.title.textContent=node.label||G.types[node.type]?.label||node.type;view.card.style.left=node.position[0]+'px';view.card.style.top=node.position[1]+'px';view.card.dataset.error=String(!G.types[node.type]||node.version!==1);for(const d of G.types[node.type]?.params||[])syncParameter(node.id,d[0]);}
 C('blank-hint').hidden=doc.graph.nodes.length>0;C('node-count').textContent=doc.graph.nodes.length+' 个节点';C('formula-name').value=doc.graph.name;refreshSelection();applyView();scheduleWires();
}
function anchor(id,port){const button=sceneNodes.get(id)?.ports.get(port);if(!button)return null;const r=button.getBoundingClientRect(),world=C('composer-world').getBoundingClientRect(),z=workspace.active.editor.zoom;return [(r.left+r.width/2-world.left)/z,(r.top+r.height/2-world.top)/z];}
function wirePath(a,b){const bend=Math.max(45,Math.abs(b[0]-a[0])*.4);return `M${a[0]},${a[1]} C${a[0]+bend},${a[1]} ${b[0]-bend},${b[1]} ${b[0]},${b[1]}`;}
function scheduleWires(){if(!wiresRaf)wiresRaf=requestAnimationFrame(()=>{wiresRaf=0;renderWires();});}
function renderWires(){if(!workspace.active)return;const holder=C('composer-wires');holder.replaceChildren();for(const edge of workspace.active.graph.edges){const a=anchor(edge.from,'out'),b=anchor(edge.to,'in:'+edge.port);if(!a||!b)continue;const key=JSON.stringify([edge.from,edge.to,edge.port]),p=document.createElementNS(svgNS,'path');p.setAttribute('d',wirePath(a,b));p.dataset.edge=key;p.classList.toggle('selected',selectedEdge===key);p.setAttribute('tabindex','0');p.setAttribute('role','button');p.setAttribute('aria-label','选择连接 '+edge.from+' → '+edge.to+' '+edge.port);p.onclick=e=>{e.stopPropagation();selectedEdge=key;workspace.active.editor.selection=[];refreshSelection();connectionMessage('已选择连接：Delete 删除；添加单输入节点可插入。');};p.onkeydown=e=>{if(e.key==='Enter'){selectedEdge=key;refreshSelection();}if(['Delete','Backspace'].includes(e.key)){e.preventDefault();selectedEdge=key;removeSelection();}};holder.append(p);}
 if(gesture?.type==='wire'&&cursorWorld&&pendingPort){const pin=anchor(pendingPort.nodeId,pendingPort.direction==='out'?'out':'in:'+pendingPort.port);if(pin){const p=document.createElementNS(svgNS,'path');p.setAttribute('d',pendingPort.direction==='out'?wirePath(pin,cursorWorld):wirePath(cursorWorld,pin));p.style.stroke='var(--accent)';p.style.pointerEvents='none';holder.append(p);}}
}
const nodeResizeObserver=new ResizeObserver(scheduleWires);
graphCanvas.addEventListener('pointerdown',e=>{if(!workspace.active||e.target.closest('input,select,button'))return;if(spaceDown||e.button===1){e.preventDefault();gesture={type:'pan',start:[e.clientX,e.clientY],origin:[workspace.active.editor.x,workspace.active.editor.y]};graphCanvas.setPointerCapture(e.pointerId);return;}if(e.button!==0||e.target.closest('.orbit-node,path'))return;const r=graphCanvas.getBoundingClientRect();gesture={type:'box',start:[e.clientX-r.left,e.clientY-r.top],moved:false,add:e.shiftKey,selection:[...workspace.active.editor.selection]};graphCanvas.setPointerCapture(e.pointerId);});
document.addEventListener('pointermove',e=>{if(!gesture||!workspace.active)return;const v=workspace.active.editor;if(gesture.type==='nodes'){if(gesture.docId!==workspace.activeId)return;const p=worldPoint(e.clientX,e.clientY),dx=p[0]-gesture.start[0],dy=p[1]-gesture.start[1];if(Math.abs(dx)+Math.abs(dy)>3)gesture.moved=true;for(const [id,start]of gesture.positions){const n=currentNode(id);if(!n)continue;n.position=[start[0]+dx,start[1]+dy];const card=sceneNodes.get(id).card;card.style.left=n.position[0]+'px';card.style.top=n.position[1]+'px';}scheduleWires();}
 else if(gesture.type==='pan'){v.x=gesture.origin[0]+e.clientX-gesture.start[0];v.y=gesture.origin[1]+e.clientY-gesture.start[1];applyView();}
 else if(gesture.type==='wire'){gesture.moved ||= Math.hypot(e.clientX-gesture.start[0],e.clientY-gesture.start[1])>5;if(gesture.moved)pendingPort=gesture.port;cursorWorld=worldPoint(e.clientX,e.clientY);scheduleWires();}
 else if(gesture.type==='box'){const r=graphCanvas.getBoundingClientRect(),p=[e.clientX-r.left,e.clientY-r.top];gesture.end=p;gesture.moved ||= Math.hypot(p[0]-gesture.start[0],p[1]-gesture.start[1])>4;const b=C('selection-box');b.hidden=!gesture.moved;b.style.left=Math.min(p[0],gesture.start[0])+'px';b.style.top=Math.min(p[1],gesture.start[1])+'px';b.style.width=Math.abs(p[0]-gesture.start[0])+'px';b.style.height=Math.abs(p[1]-gesture.start[1])+'px';}});
document.addEventListener('pointerup',e=>{if(!gesture)return;const action=gesture;gesture=null;cursorWorld=null;C('selection-box').hidden=true;
 if(action.type==='nodes'&&action.moved&&action.docId===workspace.activeId){const next=G.clone(workspace.active.graph);workspace.active.graph=action.before;workspace.active.change(g=>{g.nodes=next.nodes;});ignoreClick=true;saveSoon();updateUndo();}
 else if(action.type==='wire'&&action.moved&&pendingPort){skipPortClick=true;const target=document.elementFromPoint(e.clientX,e.clientY)?.closest('.orbit-port'),pending=pendingPort;if(target&&target.dataset.direction!==pending.direction){if(pending.direction==='out')connect(pending.nodeId,target.dataset.node,target.dataset.port);else connect(target.dataset.node,pending.nodeId,pending.port);}else if(!target)openLibrary(pending);}
 else if(action.type==='box'){if(action.moved){const r=graphCanvas.getBoundingClientRect(),a=worldPoint(r.left+action.start[0],r.top+action.start[1]),b=worldPoint(r.left+action.end[0],r.top+action.end[1]);const nodes=workspace.active.graph.nodes.filter(n=>n.position[0]<Math.max(a[0],b[0])&&n.position[0]+240>Math.min(a[0],b[0])&&n.position[1]<Math.max(a[1],b[1])&&n.position[1]+(sceneNodes.get(n.id)?.card.offsetHeight||200)>Math.min(a[1],b[1]));workspace.active.editor.selection=[...new Set([...(action.add?action.selection:[]),...nodes.map(n=>n.id)])];}else if(!pendingPort)workspace.active.editor.selection=[];selectedEdge=null;refreshSelection();}
 saveSoon();scheduleWires();});
document.addEventListener('pointercancel',()=>{if(gesture?.type==='nodes'&&gesture.docId===workspace.activeId){workspace.active.graph=gesture.before;renderScene();}gesture=null;cursorWorld=null;C('selection-box').hidden=true;scheduleWires();});
graphCanvas.addEventListener('wheel',e=>{e.preventDefault();const r=graphCanvas.getBoundingClientRect(),v=workspace.active.editor,px=e.clientX-r.left,py=e.clientY-r.top,old=v.zoom;v.zoom=Math.max(.15,Math.min(1.8,old*Math.exp(-e.deltaY*.001)));v.x=px-(px-v.x)*v.zoom/old;v.y=py-(py-v.y)*v.zoom/old;applyView();saveSoon();},{passive:false});
graphCanvas.ondblclick=e=>{if(!e.target.closest('.orbit-node,path'))openLibrary();};graphCanvas.oncontextmenu=e=>{e.preventDefault();if(!e.target.closest('.orbit-node'))openLibrary(selectedEdge?{edge:JSON.parse(selectedEdge)}:null);};
document.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea'))return;if(e.code==='Space'&&graphCanvas.contains(e.target)){spaceDown=true;e.preventDefault();}if(e.key==='Escape'){pendingPort=null;gesture=null;C('node-library').hidden=true;advancedOpen(false);scheduleWires();}if(!graphCanvas.contains(e.target)&&e.target!==document.body)return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();(e.shiftKey?C('redo-graph'):C('undo-graph')).click();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='c'){e.preventDefault();copySelection();}else if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='v'){e.preventDefault();pasteSelection();}else if(['Delete','Backspace'].includes(e.key)){e.preventDefault();removeSelection();}else if(e.shiftKey&&e.key.toLowerCase()==='a'){e.preventDefault();openLibrary();}else if(e.key.toLowerCase()==='f'){e.preventDefault();focusNodes();}else if(e.key==='Home'){e.preventDefault();focusNodes(true);}});
document.addEventListener('keyup',e=>{if(e.code==='Space')spaceDown=false;});
let previousCanvasSize=null;new ResizeObserver(entries=>{const r=entries[0].contentRect;if(workspace.active&&previousCanvasSize&&!gesture){workspace.active.editor.x+=(r.width-previousCanvasSize.width)/2;workspace.active.editor.y+=(r.height-previousCanvasSize.height)/2;applyView();}previousCanvasSize={width:r.width,height:r.height};}).observe(graphCanvas);


